        "footprints": () => {
      const uid = 'xx' + Math.random().toString(36).slice(2,8);
      return `
      <div id="${uid}" style="font-family:var(--font-body,Inter,sans-serif);max-width:480px">
        <style>
          #${uid} .fp-card { background:var(--surface);border:1px solid var(--border);border-radius:12px;overflow:hidden; }
          #${uid} .fp-header { padding:12px 16px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between; }
          #${uid} .fp-title { font-size:13px;font-weight:600;color:var(--fg); }
          #${uid} .fp-badge { font-size:11px;padding:2px 8px;background:var(--ink-100);border-radius:4px;color:var(--fg-muted);font-family:var(--font-mono); }
          #${uid} .fp-list { padding:0; }
          #${uid} .fp-step { border-bottom:1px solid var(--border); }
          #${uid} .fp-step:last-child { border-bottom:none; }
          #${uid} .fp-row { display:flex;align-items:center;gap:10px;padding:10px 16px;cursor:pointer;transition:background 0.1s; }
          #${uid} .fp-row:hover { background:var(--ink-25); }
          #${uid} .fp-icon { width:28px;height:28px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:12px;flex-shrink:0; }
          #${uid} .fp-icon--ok  { background:#dcfce7; }
          #${uid} .fp-icon--err { background:#fee2e2; }
          #${uid} .fp-icon--run { background:#fef9c3; }
          #${uid} .fp-tool { font-size:11px;font-family:var(--font-mono);color:var(--fg-muted);flex-shrink:0; }
          #${uid} .fp-label { flex:1;font-size:12.5px;color:var(--fg); }
          #${uid} .fp-time { font-size:10.5px;color:var(--fg-muted); }
          #${uid} .fp-caret { font-size:10px;color:var(--fg-muted);transition:transform 0.15s; }
          #${uid} .fp-detail { display:none;padding:8px 16px 12px 54px;font-size:11.5px;font-family:var(--font-mono);color:var(--fg-mid);background:var(--ink-25);border-top:1px solid var(--border);line-height:1.6; }
          #${uid} .fp-detail.open { display:block; }
          #${uid} .fp-footer { padding:10px 16px;border-top:1px solid var(--border);background:var(--ink-25);display:flex;align-items:center;justify-content:space-between; }
          #${uid} .fp-summary { font-size:11.5px;color:var(--fg-muted); }
          #${uid} .fp-export { padding:5px 12px;border-radius:6px;border:1px solid var(--border-strong);background:var(--surface);font-size:11.5px;color:var(--fg-mid);cursor:pointer;font-family:inherit;transition:all 0.12s; }
          #${uid} .fp-export:hover { border-color:var(--fg-mid);color:var(--fg); }
        </style>
        <div class="fp-card">
          <div class="fp-header">
            <span class="fp-title">Tool use log</span>
            <span class="fp-badge">3 calls</span>
          </div>
          <div class="fp-list">
            <div class="fp-step">
              <div class="fp-row" onclick="fpToggle('${uid}',0)">
                <span class="fp-icon fp-icon--ok">✓</span>
                <span class="fp-tool">email.send</span>
                <span class="fp-label">Sent email to Sam K.</span>
                <span class="fp-time">2m ago</span>
                <span class="fp-caret" id="${uid}-c0">▾</span>
              </div>
              <div class="fp-detail" id="${uid}-d0">status: 200 OK&#10;to: sam.k@acmecorp.com&#10;subject: "Quick check-in on renewal"</div>
            </div>
            <div class="fp-step">
              <div class="fp-row" onclick="fpToggle('${uid}',1)">
                <span class="fp-icon fp-icon--ok">✓</span>
                <span class="fp-tool">crm.search</span>
                <span class="fp-label">Read 3 CRM records</span>
                <span class="fp-time">8m ago</span>
                <span class="fp-caret" id="${uid}-c1">▾</span>
              </div>
              <div class="fp-detail" id="${uid}-d1">status: 200 OK&#10;query: accounts WHERE renewal_date &lt; 90d&#10;returned: 3 records</div>
            </div>
            <div class="fp-step">
              <div class="fp-row" onclick="fpToggle('${uid}',2)">
                <span class="fp-icon fp-icon--ok">✓</span>
                <span class="fp-tool">linear.create</span>
                <span class="fp-label">Created issue ENG-412</span>
                <span class="fp-time">14m ago</span>
                <span class="fp-caret" id="${uid}-c2">▾</span>
              </div>
              <div class="fp-detail" id="${uid}-d2">status: 201 Created&#10;id: ENG-412&#10;title: "Fix CRM token refresh"</div>
            </div>
          </div>
          <div class="fp-footer">
            <span class="fp-summary">3 calls · 0 errors · this session</span>
            <button class="fp-export" id="${uid}-exp" onclick="fpExport('${uid}')">Export log</button>
          </div>
        </div>
      </div>
      <script>
      (function(){
        function fpToggle(uid, idx) {
          var d = document.getElementById(uid+'-d'+idx);
          var c = document.getElementById(uid+'-c'+idx);
          if (!d) return;
          var open = d.classList.toggle('open');
          if (c) c.style.transform = open ? 'rotate(180deg)' : '';
        }
        function fpExport(uid) {
          var btn = document.getElementById(uid+'-exp');
          if (!btn) return;
          btn.textContent = 'Exporting…'; btn.disabled = true;
          setTimeout(function(){
            btn.textContent = '✓ Exported'; btn.style.color = '#16a34a';
            setTimeout(function(){ btn.textContent = 'Export log'; btn.style.color = ''; btn.disabled = false; }, 2000);
          }, 800);
        }
        window.fpToggle = fpToggle;
        window.fpExport = fpExport;
      })();
      </script>
      `;
    },

